content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-gradient: linear-gradient(135deg, #f0fdf4 0%, #e0f2fe 50%, #fef3c7 100%);
  --surface-color: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --action-color: #10b981;
  --action-hover: #059669;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text-main);
  background: var(--bg-gradient);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体ラッパー */
.app-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 20px 32px 20px;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 20px;
}

.app-title {
  font-size: 1.85rem;
  font-weight: 800;
  color: #1e293b;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* メイン描画エリア＆ツールバーのコンテナ */
.main-board-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--surface-color);
  padding: 18px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(255, 255, 255, 0.7);
}

/* ツールバーコンテナ */
.toolbar-container {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

/* 各セクション */
.toolbar-section {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.toolbar-label {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* カラーパレット */
.color-palette {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.color-swatch {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  outline: 1px solid var(--border-color);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  padding: 0;
}

.color-swatch:hover {
  transform: scale(1.15);
}

.color-swatch-active {
  transform: scale(1.22);
  outline: 2px solid var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.35);
}

/* カスタムカラーピッカー */
.custom-color-picker {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: 32px;
  height: 32px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  border-radius: 50%;
  padding: 0;
  overflow: hidden;
}

.custom-color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.custom-color-picker::-webkit-color-swatch {
  border: 2px solid #ffffff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px var(--border-color);
}

/* 太さスライダー */
.size-slider-wrapper {
  display: flex;
  align-items: center;
  gap: 12px;
}

.size-slider {
  width: 120px;
  cursor: pointer;
  accent-color: var(--primary-color);
}

.size-preview-circle {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  min-height: 34px;
  background: #f8fafc;
  border-radius: 50%;
  border: 1px solid var(--border-color);
}

/* ボタングループ */
.tool-btn-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* 基本ツールボタン */
.tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background-color: #ffffff;
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
  min-height: 38px;
}

.tool-btn:hover:not(:disabled) {
  background-color: #f3f4f6;
  border-color: #d1d5db;
}

.tool-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.tool-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* アクティブボタン（ペン・消しゴム選択中） */
.tool-btn-active {
  background-color: var(--primary-color);
  border-color: var(--primary-color);
  color: #ffffff;
}

.tool-btn-active:hover:not(:disabled) {
  background-color: var(--primary-hover);
  border-color: var(--primary-hover);
}

/* 危険系ボタン（全消去） */
.tool-btn-danger {
  color: var(--danger-color);
  border-color: #fecaca;
  background-color: #fef2f2;
}

.tool-btn-danger:hover:not(:disabled) {
  background-color: var(--danger-color);
  border-color: var(--danger-color);
  color: #ffffff;
}

/* アクションボタン（保存・ダウンロード） */
.tool-btn-action {
  background-color: var(--action-color);
  border-color: var(--action-color);
  color: #ffffff;
}

.tool-btn-action:hover:not(:disabled) {
  background-color: var(--action-hover);
  border-color: var(--action-hover);
}

/* キャンバス描画エリアラッパー */
.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  min-height: 280px;
  max-height: 65vh;
  background-color: #ffffff;
  border-radius: var(--radius-md);
  border: 2px dashed #cbd5e1;
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.03);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* キャンバス本体 */
.drawing-canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .app-wrapper {
    padding: 10px;
  }

  .main-board-container {
    padding: 12px;
  }

  .canvas-wrapper {
    aspect-ratio: 4 / 3;
    min-height: 260px;
  }

  .toolbar-container {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .toolbar-section {
    justify-content: space-between;
    width: 100%;
  }

  .tool-btn-group {
    width: 100%;
    justify-content: space-between;
  }

  .tool-btn {
    flex: 1;
    padding: 8px 8px;
    font-size: 0.85rem;
  }

  .size-slider {
    width: 100px;
  }
}

@media (max-width: 480px) {
  .app-title {
    font-size: 1.4rem;
  }

  .canvas-wrapper {
    aspect-ratio: 1 / 1;
    min-height: 240px;
  }

  .color-swatch {
    width: 24px;
    height: 24px;
  }
}

export type ToolMode = 'pen' | 'eraser';

export interface DrawSettings {
  color: string;
  brushSize: number;
  mode: ToolMode;
}

export interface ToolbarProps {
  settings: DrawSettings;
  onSettingsChange: (newSettings: DrawSettings) => void;
  onClear: () => void;
  onUndo: () => void;
  canUndo: boolean;
  onDownload: () => void;
}

export interface CanvasBoardHandle {
  clear: () => void;
  undo: () => void;
  downloadImage: (filename?: string) => void;
  getDataUrl: () => string;
}

export interface CanvasBoardProps {
  settings: DrawSettings;
  onHistoryChange?: (canUndo: boolean) => void;
}

import { ChangeEvent } from 'react';
import { ToolbarProps } from '../types';
import { PRESET_COLORS } from '../constants/colors';

const Toolbar = ({
  settings,
  onSettingsChange,
  onClear,
  onUndo,
  canUndo,
  onDownload,
}: ToolbarProps) => {
  const handleColorSelect = (selectedColor: string) => {
    onSettingsChange({
      ...settings,
      color: selectedColor,
      mode: 'pen',
    });
  };

  const handleCustomColor = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({
      ...settings,
      color: e.target.value,
      mode: 'pen',
    });
  };

  const handleSizeChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({
      ...settings,
      brushSize: Number(e.target.value),
    });
  };

  const handleModeSwitch = (mode: 'pen' | 'eraser') => {
    onSettingsChange({
      ...settings,
      mode,
    });
  };

  return (
    <div className="toolbar-container">
      {/* ツール切り替え */}
      <div className="toolbar-section">
        <span className="toolbar-label">モード</span>
        <div className="tool-btn-group" role="group" aria-label="描画ツール切り替え">
          <button
            type="button"
            className={settings.mode === 'pen' ? 'tool-btn tool-btn-active' : 'tool-btn'}
            onClick={() => handleModeSwitch('pen')}
            aria-pressed={settings.mode === 'pen'}
          >
            ✏️ ペン
          </button>
          <button
            type="button"
            className={settings.mode === 'eraser' ? 'tool-btn tool-btn-active' : 'tool-btn'}
            onClick={() => handleModeSwitch('eraser')}
            aria-pressed={settings.mode === 'eraser'}
          >
            🧹 消しゴム
          </button>
        </div>
      </div>

      {/* カラーパレット */}
      <div className="toolbar-section">
        <span className="toolbar-label">カラー</span>
        <div className="color-palette" role="group" aria-label="カラーパレット">
          {PRESET_COLORS.map((color) => {
            const isActive = settings.mode === 'pen' && settings.color.toLowerCase() === color.toLowerCase();
            return (
              <button
                key={color}
                type="button"
                className={isActive ? 'color-swatch color-swatch-active' : 'color-swatch'}
                style={{ backgroundColor: color }}
                onClick={() => handleColorSelect(color)}
                aria-label={`色 ${color}${isActive ? '（選択中）' : ''}`}
                title={color}
              />
            );
          })}
          <input
            type="color"
            className="custom-color-picker"
            value={settings.color}
            onChange={handleCustomColor}
            title="カスタムカラーを選択"
            aria-label="カスタムカラーピッカー"
          />
        </div>
      </div>

      {/* 太さスライダー & プレビュー */}
      <div className="toolbar-section">
        <label htmlFor="brush-size-slider" className="toolbar-label">
          太さ ({settings.brushSize}px)
        </label>
        <div className="size-slider-wrapper">
          <input
            id="brush-size-slider"
            type="range"
            min={1}
            max={50}
            value={settings.brushSize}
            onChange={handleSizeChange}
            className="size-slider"
            aria-label="ブラシの太さ"
          />
          <div className="size-preview-circle" title={`現在の太さ: ${settings.brushSize}px`}>
            <span
              style={{
                width: `${Math.min(settings.brushSize, 28)}px`,
                height: `${Math.min(settings.brushSize, 28)}px`,
                backgroundColor: settings.mode === 'eraser' ? '#94a3b8' : settings.color,
                borderRadius: '50%',
                display: 'block',
              }}
            />
          </div>
        </div>
      </div>

      {/* アクションボタン */}
      <div className="toolbar-section">
        <div className="tool-btn-group">
          <button
            type="button"
            className="tool-btn"
            onClick={onUndo}
            disabled={!canUndo}
            title="直前の操作を1つ戻す"
            aria-label="1つ戻す"
          >
            ↩️ 戻す
          </button>
          <button
            type="button"
            className="tool-btn tool-btn-danger"
            onClick={onClear}
            title="キャンバスを全消去"
            aria-label="全消去"
          >
            🗑️ 全消去
          </button>
          <button
            type="button"
            className="tool-btn tool-btn-action"
            onClick={onDownload}
            title="PNG画像として保存"
            aria-label="画像を保存"
          >
            💾 画像を保存
          </button>
        </div>
      </div>
    </div>
  );
};

export default Toolbar;

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import { CanvasBoardHandle, CanvasBoardProps } from '../types';

const MAX_HISTORY = 30;

const CanvasBoard = forwardRef<CanvasBoardHandle, CanvasBoardProps>(
  ({ settings, onHistoryChange }, ref) => {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const isDrawingRef = useRef(false);
    const lastPointRef = useRef<{ x: number; y: number } | null>(null);
    const historyRef = useRef<ImageData[]>([]);
    const settingsRef = useRef(settings);
    const onHistoryChangeRef = useRef(onHistoryChange);

    useEffect(() => {
      settingsRef.current = settings;
    }, [settings]);

    useEffect(() => {
      onHistoryChangeRef.current = onHistoryChange;
    }, [onHistoryChange]);

    const notifyHistoryChange = useCallback(() => {
      if (onHistoryChangeRef.current) {
        onHistoryChangeRef.current(historyRef.current.length > 1);
      }
    }, []);

    // 現在のキャンバス状態を履歴に保存
    const pushHistory = useCallback(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const currentImageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      historyRef.current.push(currentImageData);

      if (historyRef.current.length > MAX_HISTORY) {
        historyRef.current.shift();
      }

      notifyHistoryChange();
    }, [notifyHistoryChange]);

    // 白背景でキャンバスを初期化
    const initCanvasBackground = useCallback(
      (ctx: CanvasRenderingContext2D, width: number, height: number) => {
        ctx.save();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, width, height);
        ctx.restore();
      },
      []
    );

    // キャンバスのリサイズおよびRetina対応
    const setupCanvas = useCallback(() => {
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const rect = container.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      const displayWidth = Math.floor(rect.width);
      const displayHeight = Math.floor(rect.height);

      if (displayWidth === 0 || displayHeight === 0) return;

      const newCanvasWidth = Math.floor(displayWidth * dpr);
      const newCanvasHeight = Math.floor(displayHeight * dpr);

      // サイズ変更がない場合はスキップ
      if (canvas.width === newCanvasWidth && canvas.height === newCanvasHeight) {
        return;
      }

      // 既存の描画内容を一時保存
      let backupCanvas: HTMLCanvasElement | null = null;
      if (canvas.width > 0 && canvas.height > 0) {
        backupCanvas = document.createElement('canvas');
        backupCanvas.width = canvas.width;
        backupCanvas.height = canvas.height;
        const backupCtx = backupCanvas.getContext('2d');
        if (backupCtx) {
          backupCtx.drawImage(canvas, 0, 0);
        }
      }

      canvas.width = newCanvasWidth;
      canvas.height = newCanvasHeight;

      // 初回または空の場合
      initCanvasBackground(ctx, canvas.width, canvas.height);

      if (backupCanvas) {
        ctx.drawImage(backupCanvas, 0, 0, canvas.width, canvas.height);
      }

      historyRef.current = [ctx.getImageData(0, 0, canvas.width, canvas.height)];
      notifyHistoryChange();
    }, [initCanvasBackground, notifyHistoryChange]);

    useEffect(() => {
      setupCanvas();

      const handleResize = () => {
        setupCanvas();
      };

      let resizeObserver: ResizeObserver | null = null;
      if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        resizeObserver = new ResizeObserver(() => {
          setupCanvas();
        });
        resizeObserver.observe(containerRef.current);
      } else {
        window.addEventListener('resize', handleResize);
      }

      return () => {
        if (resizeObserver) {
          resizeObserver.disconnect();
        } else {
          window.removeEventListener('resize', handleResize);
        }
      };
    }, [setupCanvas]);

    // ポインター座標の計算
    const getCoordinates = (e: React.PointerEvent<HTMLCanvasElement>) => {
      const canvas = canvasRef.current;
      if (!canvas) return { x: 0, y: 0 };

      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width;
      const scaleY = canvas.height / rect.height;

      return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY,
      };
    };

    // 描画設定の適用
    const applyDrawStyles = (ctx: CanvasRenderingContext2D) => {
      const dpr = window.devicePixelRatio || 1;
      const currentSettings = settingsRef.current;

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = currentSettings.brushSize * dpr;

      if (currentSettings.mode === 'eraser') {
        ctx.strokeStyle = '#ffffff';
      } else {
        ctx.strokeStyle = currentSettings.color;
      }
    };

    const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (e.button !== 0) return; // 左クリックのみ

      const canvas = canvasRef.current;
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.setPointerCapture(e.pointerId);
      isDrawingRef.current = true;

      const point = getCoordinates(e);
      lastPointRef.current = point;

      // クリックのみの場合でも点描画
      applyDrawStyles(ctx);
      ctx.beginPath();
      ctx.arc(point.x, point.y, (ctx.lineWidth || 1) / 2, 0, Math.PI * 2);
      ctx.fillStyle = ctx.strokeStyle;
      ctx.fill();
    };

    const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDrawingRef.current || !lastPointRef.current) return;

      const canvas = canvasRef.current;
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const currentPoint = getCoordinates(e);
      applyDrawStyles(ctx);

      ctx.beginPath();
      ctx.moveTo(lastPointRef.current.x, lastPointRef.current.y);
      ctx.lineTo(currentPoint.x, currentPoint.y);
      ctx.stroke();

      lastPointRef.current = currentPoint;
    };

    const endDrawing = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDrawingRef.current) return;

      const canvas = canvasRef.current;
      if (canvas && canvas.hasPointerCapture(e.pointerId)) {
        canvas.releasePointerCapture(e.pointerId);
      }

      isDrawingRef.current = false;
      lastPointRef.current = null;
      pushHistory();
    };

    // 外部から操作可能なメソッドを公開
    useImperativeHandle(
      ref,
      () => ({
        clear: () => {
          const canvas = canvasRef.current;
          if (!canvas) return;
          const ctx = canvas.getContext('2d');
          if (!ctx) return;

          initCanvasBackground(ctx, canvas.width, canvas.height);
          pushHistory();
        },
        undo: () => {
          const canvas = canvasRef.current;
          if (!canvas) return;
          const ctx = canvas.getContext('2d');
          if (!ctx) return;

          if (historyRef.current.length <= 1) return;

          // 現在の状態を取り除く
          historyRef.current.pop();
          const previousState = historyRef.current[historyRef.current.length - 1];

          if (previousState) {
            ctx.putImageData(previousState, 0, 0);
          }
          notifyHistoryChange();
        },
        downloadImage: (filename = 'my-drawing.png') => {
          const canvas = canvasRef.current;
          if (!canvas) return;

          const dataUrl = canvas.toDataURL('image/png');
          const link = document.createElement('a');
          link.download = filename;
          link.href = dataUrl;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        },
        getDataUrl: () => {
          const canvas = canvasRef.current;
          if (!canvas) return '';
          return canvas.toDataURL('image/png');
        },
      }),
      [initCanvasBackground, notifyHistoryChange, pushHistory]
    );

    return (
      <div className="canvas-wrapper" ref={containerRef}>
        <canvas
          ref={canvasRef}
          className="drawing-canvas"
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrawing}
          onPointerCancel={endDrawing}
          aria-label="お絵かきキャンバス"
          role="img"
        />
      </div>
    );
  }
);

CanvasBoard.displayName = 'CanvasBoard';

export default CanvasBoard;
